/* Design study only. No API, token, storage or paid generation code. */
const game=document.getElementById('game');
const query=new URLSearchParams(location.search);
const state={concept:query.get('concept')||'camp',screen:query.get('screen')||'select',selected:1,page:0,category:'Head',tab:'Wardrobe',dir:0,frame:0,playing:false,proof:false,head:'helmet',tone:0,light:false,overlay:null,creationStep:0};
const roster=[{name:'Mira',note:'The wayfinder',head:'hat',gear:['cape','body','vest','hair','hat']},{name:'Rowan',note:'The adventurer',head:'helmet',gear:['cape','body','vest','hair','helmet','sword']},{name:'Finn',note:'The wanderer',head:'hair',gear:['body','vest','hair']},{name:'Ember',note:'The spellkeeper',head:'hat',gear:['body','hair','hat']},{name:'Ash',note:'The guardian',head:'helmet',gear:['body','vest','helmet','sword']},{name:'Wren',note:'The traveller',head:'hair',gear:['cape','body','hair']}];
const icons=PD_ASSETS.icons;
const sprites={};
const $=s=>game.querySelector(s);
const icon=n=>icons[n]||'';
const button=(label,action,cls='ghost',ico='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const canvas=(gear,size=64,extra='')=>`<canvas width="64" height="64" role="img" aria-label="${extra||'Pixel character preview'}" data-gear="${gear.join(',')}" style="--sprite-size:${size}px"></canvas>`;
const cats=[['Head','crown'],['Hair','scissors'],['Body','shirt'],['Legs','person-standing'],['Feet','footprints'],['Back','backpack'],['Hands','sword']];
const tones=['#866444','#9b3036','#478e7c','#6e66a7','#cba665'];
const toneNames=['Leather','Crimson','Sage','Iris','Honey'];
function currentGear(){let g=[...roster[state.selected].gear].filter(x=>!['hat','helmet'].includes(x));if(state.head!=='none'&&state.head!=='hair')g.push(state.head);return g;}
function header(){return `<header class="game-header"><div class="brand">${state.screen==='select'?icon('person-standing')+`<span>PixelDoll</span><span class="wordmark-sub">Your characters</span>`:button('Characters','select','ghost','arrow-left')}${state.screen==='create'?`<div class="creation-steps"><span class="current">1 · Imagine</span><span>2 · Review</span><span>3 · Bring to life</span></div>`:''}</div><div class="header-actions">${state.screen==='select'?button('Import','import','ghost optional','upload')+button('<span class="new-label">New character</span>','create','soft','plus','aria-label="New character"'):state.screen==='dress'?button('Undo','undo','ghost optional','undo-2')+button('Export','export','soft','download'):button('Cancel','select','ghost')}${button('','theme','icon-button',state.light?'moon':'sun','aria-label="Switch appearance"')}${state.screen!=='create'?button('','settings','icon-button','settings-2','aria-label="Settings and connection"'):''}</div></header>`;}
function selection(){const visible=roster.slice(state.page*3,state.page*3+3);return `<div class="scene-title"><div class="eyebrow">A little world of your own</div><h1>Who will you be?</h1><p>Choose a character. Make them yours.</p>${button('All characters · 6','library','ghost list-link','search')}</div><div class="cast">${visible.map((c,i)=>{const id=state.page*3+i;return `<button class="actor ${id===state.selected?'selected':''}" data-action="character:${id}" aria-pressed="${id===state.selected}">${canvas(c.gear,64,c.name)}<b>${c.name}</b><small>${c.note}</small></button>`}).join('')}</div><div class="roster-sidebar">${visible.map((c,i)=>{const id=state.page*3+i;return `<button class="roster-person ${id===state.selected?'selected':''}" data-action="character:${id}" aria-pressed="${id===state.selected}">${canvas(c.gear,64,c.name)}<span>${c.name}<small>${c.note}</small></span></button>`}).join('')}</div><div class="select-bottom"><div class="paging">${button('','prev','', 'chevron-left','aria-label="Previous page of characters"')}${button('Customize '+roster[state.selected].name,'dress','primary','arrow-right')}${button('','next','','chevron-right','aria-label="Next page of characters"')}</div><span class="meta">${state.page+1} / 2 &nbsp; · &nbsp; 6 characters</span></div><span class="storage-note">Saved on this device &nbsp; · &nbsp; Keep a backup</span><span class="scene-note">Sample cast · existing PixelDoll artwork</span>`;}
function create(){return `<div class="scene-title"><div class="eyebrow">New character</div><h1>A new story<br>starts here.</h1><p>The body comes first.<br>Clothes and gear come next.</p></div><div class="create-guide"><div class="guide-frame">${canvas(['body'],64,'Example body, not a generated preview')}</div><span class="guide-label">Size guide · example only<br>Your character has not been drawn.</span></div><section class="creation-panel" aria-label="Imagine your character"><div class="creation-intro"><h2>Imagine your character</h2><p class="meta">Describe their appearance, not their equipment.</p></div><label class="name-field"><span class="field-label">Character name</span><input id="character-name" value="Rowan" maxlength="40"></label><label class="description-field"><span class="field-label">What do they look like?</span><textarea id="description">A friendly woodland elf with warm brown skin, a broad build and pointed ears.</textarea></label><div class="appearance-fields"><span class="field-label">Build hint</span><div class="choice-row">${['From description','Slender','Broad'].map((x,i)=>button(x,'build:'+i,i===0?'active':'')).join('')}</div><span class="meta">An appearance hint; exact shapes can vary.</span></div><div class="format-fields"><span class="field-label">Facing directions</span><div class="choice-row">${button('4 views','views:4','active')}${button('8 views','views:8')}</div><p class="meta" style="margin-top:6px">64 × 64 frames · 48 px base request · ${button('Change','format','small-link')}<br><span id="mirror-note">West is mirrored. Check handed items.</span></p></div><details><summary>Preview prompt & drawing settings</summary><p>Proposed prompt preview: a friendly woodland elf with warm brown skin, a broad build and pointed ears; plain base clothing, bald, empty hands. In production, this must use the exact submission serializer. Model: create-character-v3. View: low top-down. Seed: automatic.</p></details><div class="create-action">${button('Review drawing cost','drawing','primary','sparkles')}<p class="meta" style="margin-top:9px">Drawing uses PixelLab credits. Review the quote before starting; animation is a separate step.</p></div></section><div class="create-footer">${icon('eye')}<span>See the result before you commit to animation.</span></div>`;}
function wardrobe(){const head=state.category==='Head';const options=head?[['helmet','Steel helmet'],['hat','Wizard hat'],['none','None'],['new','New item']]:state.category==='Body'?[['vest','Leather vest'],['none','None'],['new','New item']]:state.category==='Back'?[['cape','Red cape'],['none','None'],['new','New item']]:state.category==='Hair'?[['hair','Brown hair'],['none','None'],['new','New item']]:state.category==='Hands'?[['sword','Steel sword'],['none','None'],['new','New item']]:[['none','None'],['new','New item']];return `<div class="panel-heading"><h2><button class="panel-category" data-action="categories">${state.category}${icon('chevron-right')}</button></h2><span class="meta" style="margin-left:auto">${options.filter(([x])=>!['new','none'].includes(x)).length} made</span>${button('','new-item','icon-button add-item','plus','aria-label="New item"')}</div><div class="item-grid">${options.map(([id,label])=>`<button class="item-choice ${id===state.head&&head?'selected':''} ${id==='none'||id==='new'?'blank':''}" data-action="item:${id}" aria-pressed="${id===state.head&&head}">${id==='none'?icon('x'):id==='new'?icon('plus'):canvas([id],64,label)}<small>${label}</small>${id===state.head&&head?`<span class="tick">${icon('check')}</span>`:''}</button>`).join('')}</div><hr class="panel-divider"><div class="palette-group"><span class="meta">Colour · ${state.category==='Head'?'Metal':'Material'}</span><div class="swatches">${tones.map((c,i)=>`<button class="swatch ${i===state.tone?'active':''}" data-action="tone:${i}" aria-label="${toneNames[i]} palette" aria-pressed="${i===state.tone}" style="--swatch:${c}"><span></span></button>`).join('')}</div></div><button class="small-link" data-action="tab:Colours">${icon('palette')} Edit exact palette</button><hr class="panel-divider"><div class="panel-bottom">${button('New '+state.category.toLowerCase()+' item','new-item','soft','plus')}${button('Use a saved design','designs','ghost','folder-open')}${button('Layer & visibility details','layers','small-link','layers')}</div>`;}
function panel(){if(state.tab==='Wardrobe')return wardrobe();if(state.tab==='Colours')return `<div class="panel-heading"><h2>Colours</h2>${icon('palette')}</div><p class="meta">Exact palette ramps · local changes</p><hr class="panel-divider"><div class="panel-content"><h3>Leather vest</h3><div class="swatches">${tones.map((c,i)=>`<button class="swatch ${i===state.tone?'active':''}" data-action="tone:${i}" aria-label="${toneNames[i]} palette" style="--swatch:${c}"><span></span></button>`).join('')}</div><p class="meta">${toneNames[state.tone]} · shading stays intact</p><hr class="panel-divider">${button('Save as a colour variant','save-colour','soft','bookmark')}${button('Advanced ramp editor','palette','small-link','settings-2')}</div>`;if(state.tab==='Moves')return `<div class="panel-heading"><h2>Moves</h2>${icon('person-standing')}</div><p class="meta">Preview your outfit in motion.</p><hr class="panel-divider">${button('Walk <span class="meta">4 views</span>','walk','move-row active','play')}${button('Cross punch <span class="meta">South only</span>','coverage','move-row','info')}<hr class="panel-divider">${button('Add a move','new-move','soft','plus')}${button('Review frame coverage','coverage','small-link','grid-2x2')}`;return `<div class="panel-heading"><h2>Outfits</h2>${icon('bookmark')}</div><p class="meta">A whole look, ready to wear.</p><hr class="panel-divider">${button('Adventurer','outfit:adventurer','move-row')}${button('Base only','outfit:base','move-row')}${button('Save current outfit','save-outfit','soft','plus')}`;}
function dress(){return `<div class="edit-title"><div class="eyebrow">Make it your own</div><h1>${roster[state.selected].name}</h1><p class="meta">${roster[state.selected].note} &nbsp; · &nbsp; Saved on this device</p></div><div class="hero-stage">${canvas(currentGear(),64,'Current outfit on '+roster[state.selected].name)}</div><div class="preview-tools">${button(state.playing?'Pause':'Walk','play','soft',state.playing?'pause':'play')}<div class="facing" aria-label="Facing direction">${['S','E','N','W'].map((d,i)=>button(d,'dir:'+i,state.dir===i?'active':'','','aria-label="'+['Face south','Face east','Face north','Face west, mirrored'][i]+'" aria-pressed="'+(state.dir===i)+'"')).join('')}</div>${button('Inspect','inspect','soft','grid-2x2','aria-label="Inspect all frames"')}${state.dir===3?'<span class="direction-note">West · mirrored from east</span>':''}</div>${state.head==='hat'?button('Wizard hat · north frames missing. Review','coverage','coverage-note','info'):''}<nav class="category-rail" aria-label="Equipment categories">${cats.map(([name,ico])=>button(name,'cat:'+name,'category '+(state.category===name?'active':''),ico,'aria-pressed="'+(state.category===name)+'"')).join('')}${button('All parts','categories','category more-parts','chevron-right')}</nav><section class="wardrobe-panel" aria-label="${state.tab}">${panel()}</section><nav class="mode-nav" aria-label="Character customization">${[['Wardrobe','shirt'],['Colours','palette'],['Moves','person-standing'],['Outfits','bookmark']].map(([name,ico])=>button(name,'tab:'+name,'tab-button '+(state.tab===name?'active':''),ico,'aria-pressed="'+(state.tab===name)+'"')).join('')}${button('','more','icon-button','ellipsis','aria-label="More character actions"')}</nav>`;}
function render(){game.className=state.concept+(state.light?' light':'')+(state.proof?' proof-mode':'');game.dataset.screen=state.screen;game.innerHTML='<div class="world-floor"></div>'+header()+(state.screen==='select'?selection():state.screen==='create'?create():dress());document.getElementById('concept').value=state.concept;document.getElementById('screen').value=state.screen;draw();}
function draw(){
 game.querySelectorAll('canvas[data-gear]').forEach(c=>{
  const ctx=c.getContext('2d');ctx.clearRect(0,0,64,64);ctx.imageSmoothingEnabled=false;
  const dir=c.dataset.dir!==undefined?Number(c.dataset.dir):state.screen==='dress'&&!c.closest('.item-choice')?state.dir:0;
  const row=dir===3?1:dir;const frame=state.screen==='dress'&&!c.closest('.item-choice')?state.frame:0;
  ctx.save();if(dir===3){ctx.translate(64,0);ctx.scale(-1,1);}
  for(const name of c.dataset.gear.split(',')){
   const img=sprites[name];if(!img)continue;
   const targetItem=state.tab==='Colours'?'vest':({Head:state.head,Body:'vest',Hair:'hair',Back:'cape',Hands:'sword'}[state.category]);
   if(state.tone&&state.screen==='dress'&&c.closest('.hero-stage')&&name===targetItem){
    const layer=document.createElement('canvas');layer.width=layer.height=64;const lc=layer.getContext('2d');lc.drawImage(img,(frame%8)*64,row*64,64,64,0,0,64,64);
    const data=lc.getImageData(0,0,64,64);const target=tones[state.tone].match(/\w\w/g).map(x=>parseInt(x,16));
    for(let i=0;i<data.data.length;i+=4){const l=(data.data[i]+data.data[i+1]+data.data[i+2])/3;if(data.data[i+3]&&l>48){const shade=l/140;for(let j=0;j<3;j++)data.data[i+j]=Math.min(255,target[j]*shade);}}
    lc.putImageData(data,0,0);ctx.drawImage(layer,0,0);
   }else ctx.drawImage(img,(frame%8)*64,row*64,64,64,0,0,64,64);
  }
  ctx.restore();
  if(c.closest('.item-choice')){
   const data=ctx.getImageData(0,0,64,64).data;let minX=64,minY=64,maxX=-1,maxY=-1;
   for(let y=0;y<64;y++)for(let x=0;x<64;x++)if(data[(y*64+x)*4+3]){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}
   if(maxX>=0){const w=maxX-minX+1,h=maxY-minY+1,k=Math.max(1,Math.floor(52/Math.max(w,h)));const temp=document.createElement('canvas');temp.width=temp.height=64;temp.getContext('2d').drawImage(c,0,0);ctx.clearRect(0,0,64,64);ctx.drawImage(temp,minX,minY,w,h,Math.floor((64-w*k)/2),Math.floor((64-h*k)/2),w*k,h*k);}
  }
 });
}
function toast(text){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;game.append(el);setTimeout(()=>el.remove(),4000);}
let lastFocus;
function open(title,content){lastFocus=document.activeElement;$('.overlay-backdrop')?.remove();const wrapper=document.createElement('div');wrapper.className='overlay-backdrop';wrapper.innerHTML=`<section class="overlay" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="panel-heading"><h2 id="dialog-title">${title}</h2>${button('','close','icon-button','x','aria-label="Close dialog"')}</div>${content}</section>`;game.append(wrapper);draw();wrapper.querySelector('button')?.focus();}
function close(){ $('.overlay-backdrop')?.remove();lastFocus?.isConnected&&lastFocus.focus();}
function library(){open('Your characters',`<label><span class="field-label">Find a character</span><input id="library-search" placeholder="Search by name" autocomplete="off"></label><div id="library-list">${roster.map((c,i)=>`<button class="list-row" data-action="choose:${i}" data-name="${c.name.toLowerCase()}">${canvas(c.gear,64,c.name)}<span>${c.name}<br><small class="meta">${c.note}</small></span></button>`).join('')}</div><p class="meta" style="margin-top:16px">6 sample characters · no four-character storage limit</p>`);}
function overlayFor(action){const demo=`<p class="meta">Offline design simulation. No request is sent and no credits are spent.</p>`;const map={
 'categories':['Choose a part',`${cats.map(([name,ico])=>button(name,'cat:'+name,'move-row',ico)).join('')}`],
 'settings':['Your space',`${button('Appearance · switch light / dark','theme','move-row','sun')}${button('Connect PixelLab','connect','move-row','key-round')}${button('Activity & generation history','activity','move-row','info')}${button('Import or restore a backup','import','move-row','upload')}<hr class="panel-divider"><p class="meta">Motion respects your device preference. Characters stay in this browser; export a backup to keep them safe.</p>`],
 'connect':['Connect PixelLab',`<p>Connect when you are ready to draw. Browsing, dressing and local recolouring stay available without a key.</p><p>This review prototype deliberately has no token field.</p>${demo}`],
 'activity':['Activity',`<p>No generation is running in this prototype.</p><div class="coverage"><span>${icon('check')} Local outfit changes are ready</span><span>${icon('info')} Paid actions require a separate review</span></div>${demo}`],
 'import':['Bring a character',`<p>Start with your own art or restore a PixelDoll project.</p>${button('From this device · images or project','import-file','move-row','upload')}${button('From PixelLab · connect first','connect','move-row','key-round')}<hr class="panel-divider"><p class="meta">Project backups restore layers and outfits. Standalone art needs a setup and compatibility review.</p>${demo}`],
 'import-file':['Import preview',`<p>The production flow will validate the file locally and show dimensions, facing directions and setup needs before fitting gear.</p>${demo}`],
 'format':['Drawing format',`<label>Base request size</label><div class="choice-row">${button('48 px','format48','active')}${button('56 px','format56')}</div><p class="meta" style="margin-top:16px">The current pipeline uses a 64 × 64 output cell. Larger bases leave less headroom for hats. These are request sizes, not guaranteed opaque body heights.</p><label>Camera</label><p>Low top-down · fixed for this study</p>${button('Keep settings','close','primary')}`],
 'drawing':['Before you draw',`<p>Your base appearance is drawn first. You will review it before choosing animations.</p><div class="coverage"><span>${icon('info')} Drawing quote: load from PixelLab</span><span>${icon('eye')} Appearance review comes next</span><span>${icon('person-standing')} Animation is quoted separately</span></div><p class="meta">The split draw / review / animate flow is proposed; it requires pipeline work. Do not show a made-up price.</p>${demo}${button('Simulate appearance review','appearance-review','primary')}`],
 'appearance-review':['Meet your character',`<div style="text-align:center">${canvas(['body'],64,'Existing sample body for review state')}</div><p>Example result · check the shape, face and all available views. In production this screen shows your generated body.</p>${button('Keep appearance · choose moves','choose-moves','primary')}${button('Try a different appearance · review cost','drawing','ghost')}${demo}`],
 'choose-moves':['Bring them to life',`<p>Your accepted appearance is preserved.</p><div class="coverage"><span>${icon('check')} Idle & walk · starting moves</span><span>${icon('info')} Review animation cost before starting</span><span>${icon('info')} Failed work never silently resubmits</span></div>${button('Finish simulation · customize','dress','primary')}${demo}`],
 'new-item':['Make a new item',`<label>Describe the item</label><textarea rows="3">A weathered leather traveller’s hood with a small brass clasp</textarea><label>Equipment slot</label><select><option>Head</option><option>Hair</option><option>Body</option><option>Back</option><option>Hands</option></select><p class="meta" style="margin-top:12px">Made for this character. Preview, fit across moves, then inspect before wearing.</p>${button('Review generation & fitting cost','item-cost','primary')}${demo}`],
 'item-cost':['Review item work',`<div class="coverage"><span>${icon('eye')} Dress the reference view</span><span>${icon('person-standing')} Fit to the selected moves</span><span>${icon('check')} Review alignment, grip and coverage</span></div><p>A current PixelLab quote belongs here. No automatic retries or surprise redraws.</p>${demo}${button('Return to wardrobe','close','primary')}`],
 'designs':['Saved designs',`<p>Reuse a design, then fit it to this character. Reuse is not an instant fit guarantee.</p>${button('Traveller’s hood · needs fitting','item-cost','move-row','crown')}${button('Save selected item as a design','save-design','move-row','bookmark')}${demo}`],
 'layers':['Layer & visibility',`<p>Steel helmet</p><label>When worn, hide</label><div class="choice-row">${button('Hair','toggle-layer','active')}${button('Face','toggle-layer')}</div><label>Layer order</label><div class="choice-row">${button('Move forward','layer-forward','')}${button('Move backward','layer-back','')}</div><p class="meta" style="margin-top:16px">Apply to this direction or all directions. Oversize held gear keeps the same body pivot.</p>${demo}`],
 'palette':['Exact ramp editor',`<p>Production editing maps selected palette colours directly and preserves the rest of the sprite. The prototype’s quick swatches are illustrative.</p><div class="swatches">${tones.map((c,i)=>`<button class="swatch" data-action="tone:${i}" aria-label="${toneNames[i]}" style="--swatch:${c}"><span></span></button>`).join('')}</div>${demo}`],
 'new-move':['Add a move',`<label>Move</label><select><option>Run</option><option>Cast</option><option>Hurt</option><option>Custom description</option></select><p class="meta" style="margin-top:16px">Show the base animation estimate and the separate work to fit existing equipment. Preserve existing frozen frames.</p>${button('Review animation & item work','item-cost','primary')}${demo}`],
 'coverage':['Frame coverage',`<div class="coverage"><span>${icon('check')} Walk · S / E / N / W</span><span class="warning">${icon('info')} Cross punch · south only</span><span>${icon('info')} West mirrors east · inspect grip</span></div><p>Missing cells are transparent in exported sheets. Review each item’s coverage before downloading.</p>${demo}`],
 'inspect':['Inspect your outfit',`<div class="proof-grid">${['South','East','North','West'].map((d,i)=>'<figure>'+canvas(currentGear(),64,d).replace('data-gear=', 'data-dir="'+i+'" data-gear=')+'<figcaption>'+d+'</figcaption></figure>').join('')}</div>${button('Switch world / plain backdrop','proof','soft','eye')}<div class="coverage"><span>Check all directions and animation frames</span><span>Alignment · stray pixels · grip · layer overlap</span></div>${button('Coverage details','coverage','soft','grid-2x2')}${demo}`],
 'export':['Ready for your game',`<p>Export ${roster[state.selected].name} as separate, aligned layers.</p><label>Game engine or format</label><select id="export-engine"><option>Godot</option><option>Phaser</option><option>Unity</option><option>Aseprite</option><option>PNG + JSON</option></select><div class="coverage"><span>${icon('check')} Separate layer sheets + manifest</span><span>${icon('check')} Include current outfit and saved looks</span><span class="warning">${icon('info')} Cross punch has south frames only</span></div>${button('Review coverage','coverage','small-link','grid-2x2')}${button('Preview export · no file generated','export-preview','primary','download')}${demo}`],
 'export-preview':['Export structure',`<p>body/ · equipment/ · palettes/ · manifest.json<br>Engine-specific import files follow the selected target.</p><p class="meta">Illustrative structure only. Production must retain PixelDoll’s existing manifest and exporter contracts.</p>${demo}`],
 'more':['Character actions',`${button('Saved outfits','tab:Outfits','move-row','bookmark')}${button('Saved designs','designs','move-row','folder-open')}${button('Layer & visibility','layers','move-row','layers')}${button('Rename character','rename','move-row')}${button('Export a backup','export','move-row','download')}`],
 'rename':['Character name',`<label><input id="rename-input" value="${roster[state.selected].name}" maxlength="30"></label>${button('Save name in this preview','save-name','primary')}`]
 };if(map[action]){open(...map[action]);return true;}return false;}
game.addEventListener('input',e=>{if(e.target.id==='library-search'){game.querySelectorAll('[data-name]').forEach(el=>el.hidden=!el.dataset.name.includes(e.target.value.toLowerCase()));}});
game.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;const [kind,val]=action.split(':');if(['select','create','dress'].includes(action)){state.screen=action;render();return;}if(action==='close'){close();return;}if(action==='theme'){state.light=!state.light;render();return;}if(action==='library'){library();return;}if(action==='proof'){state.proof=!state.proof;render();return;}if(kind==='character'||kind==='choose'){state.selected=Number(val);state.page=Math.floor(state.selected/3);state.head=roster[state.selected].head;render();return;}if(action==='next'||action==='prev'){state.page=1-state.page;state.selected=state.page*3+1;state.head=roster[state.selected].head;render();return;}if(kind==='cat'){state.category=val;state.tab='Wardrobe';render();return;}if(kind==='tab'){state.tab=val;render();return;}if(kind==='dir'){state.dir=Number(val);render();return;}if(action==='play'||action==='walk'){state.playing=!state.playing;render();return;}if(kind==='item'){if(val==='new'){overlayFor('new-item');return;}if(state.category==='Head'){state.head=val;render();}else toast(val==='none'?'Item removal is illustrated in this study.':'Selected '+val+' · sample equipment');return;}if(kind==='tone'){state.tone=Number(val);render();return;}if(kind==='outfit'){state.head=val==='base'?'none':'helmet';if(val==='base')roster[state.selected].gear=['body'];else roster[state.selected].gear=['cape','body','vest','hair','helmet','sword'];render();return;}if(action==='undo'){state.head=roster[state.selected].head;state.tone=0;render();toast('Preview restored');return;}if(kind==='build'||kind==='views'){b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(kind==='views')$('#mirror-note').textContent=val==='4'?'West is mirrored. Check handed items.':'Opposite views are mirrored. Check asymmetry.';return;}if(action==='toggle-layer'){b.classList.toggle('active');return;}if(action==='save-name'){const name=$('#rename-input').value.trim();if(name){roster[state.selected].name=name.replace(/[<>&"']/g,'');render();}return;}if(overlayFor(action))return;if(action.startsWith('save-'))toast('Saved for this preview only');else if(action.startsWith('format'))toast('Format choice illustrated; no generation is started.');else toast('Interaction specified for production; this is a visual study.');});
game.addEventListener('keydown',e=>{const modal=$('.overlay');if(e.key==='Escape'&&modal){close();return;}if(e.key==='Tab'&&modal){const items=[...modal.querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled&&!x.hidden);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.getElementById('concept').addEventListener('change',e=>{state.concept=e.target.value;render();});document.getElementById('screen').addEventListener('change',e=>{state.screen=e.target.value;render();});document.getElementById('frame').addEventListener('change',e=>document.body.classList.toggle('mobile',e.target.value==='mobile'));
if(query.has('capture'))document.body.classList.add('capture');
Promise.all(Object.entries(PD_ASSETS.sheets).map(([name,src])=>new Promise(resolve=>{const img=new Image();img.onload=()=>{sprites[name]=img;resolve();};img.src=src;}))).then(()=>{render();window.prototypeReady=true;});
setInterval(()=>{if(state.playing&&state.screen==='dress'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){state.frame=(state.frame+1)%8;draw();}},140);
